function updateDispersion(dt,moving,turning){const hull=Math.abs(player.turnVelocity),error=Math.abs(Math.atan2(Math.sin(aimYaw-player.yaw-player.turret.rotation.y),Math.cos(aimYaw-player.yaw-player.turret.rotation.y)));const pitchError=Math.abs(aimPitch+player.gun.rotation.x);aimBusy=pitchRate>.008||pitchError>.003||moving||!!turning||hull>.008||turretRate>.008||error>.008||!!keys.q||!!keys.e;shotBloom=smoothValue(shotBloom,0,2.4,dt);const target=Math.min(100,MIN_SPREAD+(moving?53:0)+Math.max(turning?33:0,Math.min(33,hull/.30*33))+Math.max(keys.q||keys.e?23:0,Math.min(23,turretRate/.48*23),Math.min(23,error*120),Math.min(23,pitchRate*120),Math.min(23,pitchError*220))+shotBloom);spread=target>spread?target:smoothValue(spread,target,2.1,dt);if(!aimBusy&&spread<MIN_SPREAD+.15){spread=MIN_SPREAD;shotBloom=0}}
function registerShot(origin,dir,aim,selected,radius,q){const rec={id:++shotSeq,time:+clock.toFixed(3),origin:coords(origin),direction:coords(dir),aim:coords(aim),rngPoint:coords(selected),rngRadiusPx:+radius.toFixed(2),aimScreen:{x:+q.x.toFixed(2),y:+q.y.toFixed(2)},status:'EM VOO',impact:null};shotLog.push(rec);if(shotLog.length>100)shotLog.shift();renderShotLog();return rec}
function finishShot(s,status,p,target=null,damage=0){const r=s.record;if(!r||r.status!=='EM VOO')return;r.status=status;r.impact=coords(p);r.target=target?.entry.name||null;r.damage=damage;r.flightDistance=+s.travel.toFixed(3);r.flightTime=+(clock-r.time).toFixed(3);const o=s.origin,d=s.dir.clone(),delta=p.clone().sub(o);r.lineError=+delta.clone().addScaledVector(d,-delta.dot(d)).length().toFixed(5);r.distanceFromAim=+p.distanceTo(new T.Vector3(r.aim.x,r.aim.y,r.aim.z)).toFixed(3);const item=debugRays.find(x=>x.id===r.id);if(item){item.line.geometry.setFromPoints([item.origin,p.clone()]);item.line.material.color.set(status==='TANQUE'?0x65ff9b:0xff8757);item.life=10;}renderShotLog()}
function renderShotLog(){const el=$('shotLog');if(!el)return;el.textContent=shotLog.slice(-12).reverse().map(r=>JSON.stringify(r,null,2)).join('\n────────────────────\n')}
$('debugToggle').onclick=()=>{$('shotDebug').hidden=!$('shotDebug').hidden};$('debugClose').onclick=()=>{$('shotDebug').hidden=true};$('debugClear').onclick=()=>{shotLog=[];renderShotLog()};$('debugExport').onclick=()=>{const blob=new Blob([JSON.stringify(shotLog,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wmk-shot-debug.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

const MIN_SPREAD=12;let assistEnabled=true,rayEnabled=true;const debugRays=[];
function refreshDebugState(){$('debugState').textContent='F9 RAYCAST '+(rayEnabled?'ON':'OFF')+' · F10 ASSISTÊNCIA '+(assistEnabled?'ON':'OFF')+' · F7 RNG '+($('rngEnabled').checked?'ON':'OFF');}
function drawShotRay(record,origin,dir,aim){const predicted=traceRay(origin,dir,SHOT_RANGE,player).point;const geometry=new T.BufferGeometry().setFromPoints([origin.clone(),predicted]);const material=new T.LineBasicMaterial({color:0xffda55,depthTest:false,transparent:true,opacity:.9});const line=new T.Line(geometry,material);line.renderOrder=999;scene.add(line);debugRays.push({id:record.id,line,origin:origin.clone(),life:12});while(debugRays.length>12){const old=debugRays.shift();scene.remove(old.line);old.line.geometry.dispose();old.line.material.dispose()}}
function updateDebugRays(dt){for(let i=debugRays.length-1;i>=0;i--){const item=debugRays[i];item.life-=dt;if(item.life<=0){scene.remove(item.line);item.line.geometry.dispose();item.line.material.dispose();debugRays.splice(i,1)}}}
$('rngEnabled').addEventListener('change',refreshDebugState);refreshDebugState();

let verticalSensitivity=.00015;try{const value=Number(localStorage.getItem('wmk3d-sensitivity-y'));if(value>=.00005&&value<=.0015)verticalSensitivity=value}catch{}const verticalInput=$('verticalSensitivity');verticalInput.value=verticalSensitivity;const showVertical=()=>{$('verticalValue').textContent=verticalSensitivity.toFixed(5)};showVertical();verticalInput.oninput=()=>{verticalSensitivity=Number(verticalInput.value);showVertical();try{localStorage.setItem('wmk3d-sensitivity-y',String(verticalSensitivity))}catch{}};
let mouseSensitivity=.0003;try{const saved=Number(localStorage.getItem('wmk3d-sensitivity-v2'));if(saved>=.00005&&saved<=.0015)mouseSensitivity=saved}catch{}const sensitivityInput=$('mouseSensitivity');sensitivityInput.value=mouseSensitivity;function showSensitivity(){$('sensitivityValue').textContent=mouseSensitivity.toFixed(5)}showSensitivity();sensitivityInput.oninput=()=>{mouseSensitivity=Number(sensitivityInput.value);showSensitivity();try{localStorage.setItem('wmk3d-sensitivity-v2',String(mouseSensitivity))}catch{}};$('controlClose').onclick=()=>{$('controlPanel').hidden=true;lockMouse()};

